import AppKit
import SwiftUI

enum AppleGPTKAssets {
    // Official Apple Game Porting Toolkit 4.0 tile icon
    static let iconBase64PNG = ""

    static let nsImage: NSImage = {
        guard let data = Data(base64Encoded: iconBase64PNG),
              let img = NSImage(data: data) else {
            return NSImage()
        }
        return img
    }()

    static var iconImage: Image {
        Image(nsImage: nsImage)
    }
}